from dispatchiq.helpers import route, travel_min


_INF = float("inf")

# Weight on squared overtime in the "guided" (load-balancing) objective.
# The pure search uses 0.0 (the real cost).  The balanced searches use these
# to spread overtime across technicians instead of stacking it on one of them.
_BAL_W = 0.005
_BAL_W2 = 0.02


# ---------------------------------------------------------------------------
# Route evaluation
# ---------------------------------------------------------------------------
def _sim(ctx, tech, seq):
    """Return (cost, end, overtime, feasible) for ``tech`` running ``seq``."""
    if not seq:
        return (0.0, float(tech["free_at"]), 0.0, True)
    key = (tech["id"], tuple(seq))
    m = ctx["cache"].get(key)
    if m is None:
        r = route(ctx["state"], tech, seq)
        feas = bool(r.get("feasible", True))
        cost = r["travel"] + r["weighted_late"] + r["overtime"] + r["emergency_wait"]
        end = float(r.get("end", tech["free_at"]))
        ot = float(r.get("overtime", 0.0))
        if (not feas) or cost >= 1e6:
            m = (_INF, end, ot, False)
        else:
            m = (cost, end, ot, True)
        ctx["cache"][key] = m
    return m


def _rc(ctx, tech, seq):
    return _sim(ctx, tech, seq)[0]


def _gc(ctx, tech, seq, bal_w):
    """Guided route cost: real cost plus a convex load-balancing penalty."""
    cost, end, ot, feas = _sim(ctx, tech, seq)
    if not feas:
        return _INF
    if bal_w:
        return cost + bal_w * ot * ot
    return cost


# ---------------------------------------------------------------------------
# Churn (moving jobs away from their morning technician)
# ---------------------------------------------------------------------------
def _churn(ctx, jid, from_id, to_id):
    orig = ctx["state"]["jobs"][jid].get("morning_tech")
    if orig is None:
        return 0.0
    ot = ctx["tech_by_id"].get(orig)
    if ot is None or ot["sick"]:
        return 0.0
    d = 0.0
    if from_id is not None and from_id != orig:
        d -= 20.0
    if to_id is not None and to_id != orig:
        d += 20.0
    return d


# ---------------------------------------------------------------------------
# Route ordering helpers
# ---------------------------------------------------------------------------
def _nn_order(ctx, tech, seq):
    state = ctx["state"]
    remaining = list(seq)
    out = []
    cur = tech["loc"]
    while remaining:
        best = None
        bestd = None
        for j in remaining:
            d = travel_min(state, cur, state["jobs"][j]["loc"])
            if bestd is None or d < bestd:
                bestd = d
                best = j
        out.append(best)
        cur = state["jobs"][best]["loc"]
        remaining.remove(best)
    return out


def _candidate_orders(ctx, tech, seq):
    state = ctx["state"]
    jobs = state["jobs"]
    if len(seq) <= 1:
        return [list(seq)]
    cands = [list(seq)]
    cands.append(sorted(seq, key=lambda j: (jobs[j]["latest"], jobs[j]["earliest"])))
    cands.append(sorted(seq, key=lambda j: (jobs[j]["earliest"], jobs[j]["latest"])))
    cands.append(sorted(seq, key=lambda j: (-jobs[j]["priority"], jobs[j]["latest"])))
    cands.append(sorted(seq, key=lambda j: (jobs[j]["latest"] - jobs[j]["duration"],
                                            jobs[j]["earliest"])))
    cands.append(_nn_order(ctx, tech, seq))
    cands.append(list(reversed(seq)))
    return cands


def _best_candidate(ctx, tech, seq, bal_w):
    best = None
    best_c = _INF
    for cand in _candidate_orders(ctx, tech, seq):
        c = _gc(ctx, tech, cand, bal_w)
        if c < best_c - 1e-9:
            best_c = c
            best = cand
    return best if best is not None else list(seq)


# ---------------------------------------------------------------------------
# Dropping jobs to recover feasibility
# ---------------------------------------------------------------------------
def _drop_to_feasible(ctx, tech, seq, keep=None, bal_w=0.0):
    """Drop lowest-priority jobs until ``seq`` is feasible.

    After a feasible subset is found the remaining route is re-ordered with
    the cheap candidate ordering heuristic, so that a job that only becomes
    schedulable once the route is re-sequenced is not needlessly dropped.
    """
    state = ctx["state"]
    seq = list(seq)
    if _sim(ctx, tech, seq)[3]:
        return seq, []
    dropped = []
    cands = [j for j in seq if j != keep]
    cands.sort(key=lambda j: (state["jobs"][j]["priority"],
                              -state["jobs"][j]["duration"]))
    for j in cands:
        seq.remove(j)
        dropped.append(j)
        if _sim(ctx, tech, seq)[3]:
            reordered = _best_candidate(ctx, tech, seq, bal_w)
            if _sim(ctx, tech, reordered)[3]:
                return reordered, dropped
            return seq, dropped
    if keep is not None:
        s2 = [keep]
        if _sim(ctx, tech, s2)[3]:
            dropped.extend([j for j in seq if j != keep])
            return s2, dropped
        return None, []
    return [], dropped


# ---------------------------------------------------------------------------
# Insertion of one unscheduled job
# ---------------------------------------------------------------------------
def _best_insert(ctx, plan, u, healthy, bal_w):
    state = ctx["state"]
    job_u = state["jobs"][u]
    p_u = job_u["priority"]
    is_em = job_u["emergency"]
    best_delta = _INF
    best = None
    for t in healthy:
        if job_u["skill"] not in t["skills"]:
            continue
        seq = plan[t["id"]]
        c_old = _gc(ctx, t, seq, bal_w)
        if c_old >= _INF:
            continue
        L = len(seq)

        # --- plain insertion ---
        for pos in range(L + 1):
            cand = seq[:pos] + [u] + seq[pos:]
            c = _gc(ctx, t, cand, bal_w)
            if c < _INF:
                delta = c - c_old - 150.0 * p_u + _churn(ctx, u, None, t["id"])
                if delta < best_delta - 1e-9:
                    best_delta = delta
                    best = (t["id"], cand)

        # --- insert with a single drop ---
        for i in range(L):
            j = seq[i]
            p_j = state["jobs"][j]["priority"]
            if not is_em and p_j > p_u:
                continue
            base = seq[:i] + seq[i + 1:]
            for pos in range(len(base) + 1):
                cand = base[:pos] + [u] + base[pos:]
                c = _gc(ctx, t, cand, bal_w)
                if c < _INF:
                    delta = c - c_old - 150.0 * p_u + 150.0 * p_j
                    delta += _churn(ctx, u, None, t["id"])
                    delta += _churn(ctx, j, t["id"], None)
                    if delta < best_delta - 1e-9:
                        best_delta = delta
                        best = (t["id"], cand)

        # --- insert with multiple greedy drops ---
        for pos in range(L + 1):
            cand = seq[:pos] + [u] + seq[pos:]
            kept, dropped = _drop_to_feasible(ctx, t, cand, keep=u, bal_w=bal_w)
            if kept is None or u not in kept:
                continue
            if len(dropped) <= 1:
                continue
            if not is_em:
                ok = True
                for j in dropped:
                    if state["jobs"][j]["priority"] > p_u:
                        ok = False
                        break
                if not ok:
                    continue
            c = _gc(ctx, t, kept, bal_w)
            if c >= _INF:
                continue
            delta = c - c_old - 150.0 * p_u
            for j in dropped:
                delta += 150.0 * state["jobs"][j]["priority"]
                delta += _churn(ctx, j, t["id"], None)
            delta += _churn(ctx, u, None, t["id"])
            if delta < best_delta - 1e-9:
                best_delta = delta
                best = (t["id"], kept)
    return best, best_delta


# ---------------------------------------------------------------------------
# Local route improvement
# ---------------------------------------------------------------------------
def _two_opt_once(ctx, tech, seq, bal_w):
    n = len(seq)
    if n < 3:
        return list(seq)
    cur = list(seq)
    c_cur = _gc(ctx, tech, cur, bal_w)
    if c_cur >= _INF:
        return cur
    for i in range(n - 1):
        for j in range(i + 1, n):
            new = cur[:i] + list(reversed(cur[i:j + 1])) + cur[j + 1:]
            c = _gc(ctx, tech, new, bal_w)
            if c < c_cur - 1e-9:
                return new
    return cur


def _or_opt_once(ctx, tech, seq, bal_w):
    n = len(seq)
    if n < 2:
        return list(seq)
    cur = list(seq)
    c_cur = _gc(ctx, tech, cur, bal_w)
    if c_cur >= _INF:
        return cur
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            new = cur[:i] + cur[i + 1:]
            new = new[:j] + [cur[i]] + new[j:]
            c = _gc(ctx, tech, new, bal_w)
            if c < c_cur - 1e-9:
                return new
    return cur


def _optimize(ctx, tech, seq, bal_w, rounds=5):
    if not seq:
        return []
    cur = _best_candidate(ctx, tech, seq, bal_w)
    c_cur = _gc(ctx, tech, cur, bal_w)
    for _ in range(rounds):
        new = _two_opt_once(ctx, tech, cur, bal_w)
        c_new = _gc(ctx, tech, new, bal_w)
        if c_new < c_cur - 1e-9:
            cur = new
            c_cur = c_new
            continue
        new = _or_opt_once(ctx, tech, cur, bal_w)
        c_new = _gc(ctx, tech, new, bal_w)
        if c_new < c_cur - 1e-9:
            cur = new
            c_cur = c_new
        else:
            break
    return cur


# ---------------------------------------------------------------------------
# Inter-route moves
# ---------------------------------------------------------------------------
def _relocate(ctx, plan, healthy, bal_w):
    state = ctx["state"]
    for t1 in healthy:
        seq1 = plan[t1["id"]]
        if not seq1:
            continue
        c1_old = _gc(ctx, t1, seq1, bal_w)
        for i in range(len(seq1)):
            jid = seq1[i]
            job = state["jobs"][jid]
            new_seq1 = seq1[:i] + seq1[i + 1:]
            c1_new = _gc(ctx, t1, new_seq1, bal_w)
            if c1_new >= _INF:
                continue
            for t2 in healthy:
                if t2["id"] == t1["id"]:
                    continue
                if job["skill"] not in t2["skills"]:
                    continue
                seq2 = plan[t2["id"]]
                c2_old = _gc(ctx, t2, seq2, bal_w)
                if c2_old >= _INF:
                    continue
                for pos in range(len(seq2) + 1):
                    new_seq2 = seq2[:pos] + [jid] + seq2[pos:]
                    c2_new = _gc(ctx, t2, new_seq2, bal_w)
                    if c2_new >= _INF:
                        continue
                    delta = (c1_new - c1_old) + (c2_new - c2_old)
                    delta += _churn(ctx, jid, t1["id"], t2["id"])
                    if delta < -1e-9:
                        plan[t1["id"]] = new_seq1
                        plan[t2["id"]] = new_seq2
                        return True
    return False


def _swap(ctx, plan, healthy, bal_w):
    state = ctx["state"]
    for a in range(len(healthy)):
        t1 = healthy[a]
        seq1 = plan[t1["id"]]
        if not seq1:
            continue
        c1_old = _gc(ctx, t1, seq1, bal_w)
        for b in range(a + 1, len(healthy)):
            t2 = healthy[b]
            seq2 = plan[t2["id"]]
            if not seq2:
                continue
            c2_old = _gc(ctx, t2, seq2, bal_w)
            for p1 in range(len(seq1)):
                jid1 = seq1[p1]
                if state["jobs"][jid1]["skill"] not in t2["skills"]:
                    continue
                for p2 in range(len(seq2)):
                    jid2 = seq2[p2]
                    if state["jobs"][jid2]["skill"] not in t1["skills"]:
                        continue
                    new1 = seq1[:p1] + [jid2] + seq1[p1 + 1:]
                    new2 = seq2[:p2] + [jid1] + seq2[p2 + 1:]
                    c1n = _gc(ctx, t1, new1, bal_w)
                    c2n = _gc(ctx, t2, new2, bal_w)
                    if c1n >= _INF or c2n >= _INF:
                        continue
                    delta = (c1n - c1_old) + (c2n - c2_old)
                    delta += _churn(ctx, jid1, t1["id"], t2["id"])
                    delta += _churn(ctx, jid2, t2["id"], t1["id"])
                    if delta < -1e-9:
                        plan[t1["id"]] = new1
                        plan[t2["id"]] = new2
                        return True
    return False


def _eject_insert(ctx, plan, healthy, u, bal_w):
    """Insert ``u`` by removing a lower-priority job and re-inserting it elsewhere."""
    state = ctx["state"]
    job_u = state["jobs"][u]
    p_u = job_u["priority"]
    is_em_u = job_u["emergency"]
    for t in healthy:
        if job_u["skill"] not in t["skills"]:
            continue
        seq = plan[t["id"]]
        c_old = _gc(ctx, t, seq, bal_w)
        if c_old >= _INF:
            continue
        for i in range(len(seq)):
            j = seq[i]
            p_j = state["jobs"][j]["priority"]
            if not is_em_u and p_j > p_u:
                continue
            base = seq[:i] + seq[i + 1:]
            best_c = _INF
            best_seq = None
            for pos in range(len(base) + 1):
                cand = base[:pos] + [u] + base[pos:]
                c = _gc(ctx, t, cand, bal_w)
                if c < best_c - 1e-9:
                    best_c = c
                    best_seq = cand
            if best_seq is None or best_c >= _INF:
                continue
            for t2 in healthy:
                if t2["id"] == t["id"]:
                    continue
                if state["jobs"][j]["skill"] not in t2["skills"]:
                    continue
                seq2 = plan[t2["id"]]
                c2_old = _gc(ctx, t2, seq2, bal_w)
                if c2_old >= _INF:
                    continue
                best_c2 = _INF
                best_seq2 = None
                for pos in range(len(seq2) + 1):
                    cand2 = seq2[:pos] + [j] + seq2[pos:]
                    c2 = _gc(ctx, t2, cand2, bal_w)
                    if c2 < best_c2 - 1e-9:
                        best_c2 = c2
                        best_seq2 = cand2
                if best_seq2 is None or best_c2 >= _INF:
                    continue
                delta = (best_c - c_old) + (best_c2 - c2_old) - 150.0 * p_u
                delta += _churn(ctx, u, None, t["id"])
                delta += _churn(ctx, j, t["id"], t2["id"])
                if delta < -1e-9:
                    plan[t["id"]] = best_seq
                    plan[t2["id"]] = best_seq2
                    return True
    return False


def _unschedule(ctx, plan, healthy, bal_w):
    state = ctx["state"]
    for t in healthy:
        seq = plan[t["id"]]
        if not seq:
            continue
        c_old = _gc(ctx, t, seq, bal_w)
        for i in range(len(seq)):
            jid = seq[i]
            job = state["jobs"][jid]
            if job["emergency"]:
                continue
            new_seq = seq[:i] + seq[i + 1:]
            c_new = _gc(ctx, t, new_seq, bal_w)
            if c_new >= _INF:
                continue
            delta = c_new - c_old + 150.0 * job["priority"]
            delta += _churn(ctx, jid, t["id"], None)
            if delta < -1e-9:
                plan[t["id"]] = new_seq
                return True
    return False


# ---------------------------------------------------------------------------
# Emergency fallback
# ---------------------------------------------------------------------------
def _force_emergency(ctx, plan, healthy, u):
    state = ctx["state"]
    job = state["jobs"][u]
    for t in healthy:
        if job["skill"] not in t["skills"]:
            continue
        seq = plan[t["id"]]
        for pos in range(len(seq) + 1):
            cand = seq[:pos] + [u] + seq[pos:]
            kept, dropped = _drop_to_feasible(ctx, t, cand, keep=u)
            if kept is not None and u in kept:
                plan[t["id"]] = kept
                return True
    return False


def _force_emergencies(ctx, plan, healthy):
    state = ctx["state"]
    assigned = set()
    for t in healthy:
        assigned.update(plan[t["id"]])
    for jid, job in state["jobs"].items():
        if job["emergency"] and jid not in assigned:
            if _force_emergency(ctx, plan, healthy, jid):
                assigned.add(jid)


# ---------------------------------------------------------------------------
# Local search
# ---------------------------------------------------------------------------
def _local_search(ctx, plan, healthy, bal_w, max_iters=30):
    state = ctx["state"]
    for _ in range(max_iters):
        improved = False

        # 1. polish every route
        for t in healthy:
            seq = plan[t["id"]]
            if len(seq) < 2:
                continue
            new = _optimize(ctx, t, seq, bal_w)
            if _gc(ctx, t, new, bal_w) < _gc(ctx, t, seq, bal_w) - 1e-9:
                plan[t["id"]] = new
                improved = True

        # 2. insert unscheduled jobs (emergencies first)
        assigned = set()
        for t in healthy:
            assigned.update(plan[t["id"]])
        unsched = [j for j in state["jobs"] if j not in assigned]
        unsched.sort(key=lambda j: (not state["jobs"][j]["emergency"],
                                    -state["jobs"][j]["priority"],
                                    state["jobs"][j]["release"]))
        for u in unsched:
            job = state["jobs"][u]
            best, bd = _best_insert(ctx, plan, u, healthy, bal_w)
            if best is not None and (job["emergency"] or bd < -1e-9):
                plan[best[0]] = best[1]
                improved = True

        if improved:
            continue

        # 3. move a single job to another technician
        if _relocate(ctx, plan, healthy, bal_w):
            continue

        # 4. swap jobs between two technicians
        if _swap(ctx, plan, healthy, bal_w):
            continue

        # 5. ejection chain
        assigned = set()
        for t in healthy:
            assigned.update(plan[t["id"]])
        unsched = [j for j in state["jobs"] if j not in assigned]
        unsched.sort(key=lambda j: (not state["jobs"][j]["emergency"],
                                    -state["jobs"][j]["priority"],
                                    state["jobs"][j]["release"]))
        ej = False
        for u in unsched:
            if _eject_insert(ctx, plan, healthy, u, bal_w):
                ej = True
                break
        if ej:
            continue

        # 6. drop a non-emergency job when that helps
        if _unschedule(ctx, plan, healthy, bal_w):
            continue

        break

    # final route polish
    for t in healthy:
        seq = plan[t["id"]]
        if len(seq) >= 2:
            new = _optimize(ctx, t, seq, bal_w)
            if _gc(ctx, t, new, bal_w) < _gc(ctx, t, seq, bal_w) - 1e-9:
                plan[t["id"]] = new
    return plan


# ---------------------------------------------------------------------------
# Pure-cost evaluation of a whole plan (for choosing between candidate plans)
# ---------------------------------------------------------------------------
def _total_cost(ctx, plan, healthy):
    state = ctx["state"]
    jobs = state["jobs"]
    total = 0.0
    assigned = set()
    for t in healthy:
        seq = plan[t["id"]]
        total += _rc(ctx, t, seq)
        assigned.update(seq)
    for t in healthy:
        for j in plan[t["id"]]:
            orig = jobs[j].get("morning_tech")
            if orig is None or orig == t["id"]:
                continue
            ot = ctx["tech_by_id"].get(orig)
            if ot is None or ot["sick"]:
                continue
            total += 20.0
    for jid, job in jobs.items():
        if jid not in assigned:
            total += 150.0 * job["priority"]
    return total


# ---------------------------------------------------------------------------
# Greedy "from scratch" construction (high priority first)
# ---------------------------------------------------------------------------
def _greedy_start(ctx, healthy, bal_w=0.0):
    state = ctx["state"]
    plan = {t["id"]: [] for t in healthy}
    order = sorted(state["jobs"],
                   key=lambda j: (not state["jobs"][j]["emergency"],
                                  -state["jobs"][j]["priority"],
                                  state["jobs"][j]["release"],
                                  j))
    for u in order:
        job = state["jobs"][u]
        best, bd = _best_insert(ctx, plan, u, healthy, bal_w)
        if best is not None and (job["emergency"] or bd < -1e-9):
            plan[best[0]] = best[1]
    return plan


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------
def replan(state):
    ctx = {
        "state": state,
        "cache": {},
        "tech_by_id": {t["id"]: t for t in state["techs"]},
    }
    healthy = [t for t in state["techs"] if not t["sick"]]

    # --- initial plan: each healthy technician keeps the jobs he still owes ---
    init = {}
    for t in healthy:
        seq = list(t["remaining"])
        if not _sim(ctx, t, seq)[3]:
            seq, _ = _drop_to_feasible(ctx, t, seq)
            if seq is None:
                seq = []
        init[t["id"]] = seq

    for t in healthy:
        init[t["id"]] = _optimize(ctx, t, init[t["id"]], 0.0)

    candidates = []

    # --- search A: pure cost from the morning-plan start (baseline quality) ---
    solid = {t["id"]: list(init[t["id"]]) for t in healthy}
    _local_search(ctx, solid, healthy, 0.0, max_iters=25)
    _force_emergencies(ctx, solid, healthy)
    candidates.append(solid)

    # --- search B: load-balanced objective (spread overtime / use slack) ---
    balanced = {t["id"]: list(init[t["id"]]) for t in healthy}
    _local_search(ctx, balanced, healthy, _BAL_W, max_iters=20)
    _force_emergencies(ctx, balanced, healthy)
    candidates.append(balanced)

    # --- search C: stronger load balancing ---
    balanced2 = {t["id"]: list(init[t["id"]]) for t in healthy}
    _local_search(ctx, balanced2, healthy, _BAL_W2, max_iters=15)
    _force_emergencies(ctx, balanced2, healthy)
    candidates.append(balanced2)

    # --- search D: greedy construction from scratch, high-priority jobs first.
    #     This explores a different basin and tends to schedule the expensive
    #     (high-priority) jobs even when they would otherwise be crowded out
    #     by low-priority jobs inherited from the morning plan. ---
    scratch = _greedy_start(ctx, healthy, 0.0)
    _local_search(ctx, scratch, healthy, 0.0, max_iters=25)
    _force_emergencies(ctx, scratch, healthy)
    candidates.append(scratch)

    # --- keep the plan with the lowest true cost ---
    chosen = None
    best_cost = _INF
    for plan in candidates:
        c = _total_cost(ctx, plan, healthy)
        if c < best_cost - 1e-9:
            best_cost = c
            chosen = plan

    # --- short pure-cost polish on the winner ---
    _local_search(ctx, chosen, healthy, 0.0, max_iters=12)
    _force_emergencies(ctx, chosen, healthy)

    return {t["id"]: chosen[t["id"]] for t in healthy}
